import {api,token,personal,el} from './common.js';
document.querySelector('#back').href=personal('/');const form=document.querySelector('#message-form'),writer=document.querySelector('#writer-status'),wall=document.querySelector('#wall-status'),list=document.querySelector('#messages'),more=document.querySelector('#more-messages');let offset=0,busy=false;
if(location.hash==='#escrever')document.querySelector('#escrever').open=true;
async function load(reset=false){if(busy)return;busy=true;more.disabled=true;try{if(reset)offset=0;const data=await api('/api/messages?offset='+offset);if(reset)list.replaceChildren();for(const m of data.messages){const card=el('article',undefined,'panel message-card'),time=el('time',new Intl.DateTimeFormat('pt-MZ',{dateStyle:'long',timeZone:'Africa/Maputo'}).format(new Date(m.created_at)));time.dateTime=new Date(m.created_at).toISOString();card.append(el('blockquote',m.message),el('div',m.author,'message-author'),time);list.append(card)}offset+=data.messages.length;more.hidden=!data.hasMore;wall.textContent=offset?'':'Seja a primeira pessoa a deixar uma mensagem de carinho.'}catch(e){wall.textContent=e.message}finally{busy=false;more.disabled=false}}
async function setup(){if(!token){writer.textContent='Abra esta página através do seu convite pessoal para escrever aos noivos.';return}try{const [{guest},{message}]=await Promise.all([api('/api/invite'),api('/api/messages/mine')]);const people=document.querySelector('#message-person');for(const [value,name]of [['primary',guest.name],...(guest.companion?[['companion',guest.companion]]:[])]){const o=el('option',name);o.value=value;people.append(o)}if(message){document.querySelector('#message-text').value=message.message;people.value=message.author===guest.companion?'companion':'primary'}form.hidden=false;writer.textContent='Será uma alegria ler as suas palavras.'}catch(e){writer.textContent=e.message}}
form.onsubmit=async e=>{e.preventDefault();const button=document.querySelector('#send-message');button.disabled=true;try{await api('/api/messages',{method:'POST',body:{person:document.querySelector('#message-person').value,message:document.querySelector('#message-text').value}});writer.textContent='Mensagem guardada. Obrigado pelo carinho!';await load(true)}catch(e){writer.textContent=e.message}finally{button.disabled=false}};more.onclick=()=>load();load(true);setup();